            'sylius.security.admin_regex' => '^/'.$container->getEnv('string:resolve:SYLIUS_ADMIN_ROUTING_PATH_NAME'),
            'sylius.security.shop_regex' => '^/(?!'.$container->getEnv('string:resolve:SYLIUS_ADMIN_ROUTING_PATH_NAME').'|api/.*|api$|media/.*)[^/]++',
            'sylius.api.authorization_header' => $container->getEnv('resolve:SYLIUS_API_AUTHORIZATION_HEADER'),
